// SPDX-License-Identifier: MIT
pragma solidity 0.8.17;

// ERC-3643 (T-REX) implementation contracts — the compliance base layer (ADR-0002).
import { Token } from "@tokenysolutions/t-rex/contracts/token/Token.sol";
import { ClaimTopicsRegistry } from
    "@tokenysolutions/t-rex/contracts/registry/implementation/ClaimTopicsRegistry.sol";
import { TrustedIssuersRegistry } from
    "@tokenysolutions/t-rex/contracts/registry/implementation/TrustedIssuersRegistry.sol";
import { IdentityRegistryStorage } from
    "@tokenysolutions/t-rex/contracts/registry/implementation/IdentityRegistryStorage.sol";
import { IdentityRegistry } from
    "@tokenysolutions/t-rex/contracts/registry/implementation/IdentityRegistry.sol";
import { ModularCompliance } from
    "@tokenysolutions/t-rex/contracts/compliance/modular/ModularCompliance.sol";
import { TREXImplementationAuthority } from
    "@tokenysolutions/t-rex/contracts/proxy/authority/TREXImplementationAuthority.sol";
import { ITREXImplementationAuthority } from
    "@tokenysolutions/t-rex/contracts/proxy/authority/ITREXImplementationAuthority.sol";
import { TREXFactory } from "@tokenysolutions/t-rex/contracts/factory/TREXFactory.sol";
import { ITREXFactory } from "@tokenysolutions/t-rex/contracts/factory/ITREXFactory.sol";
import { IToken } from "@tokenysolutions/t-rex/contracts/token/IToken.sol";
import { IIdentityRegistry } from
    "@tokenysolutions/t-rex/contracts/registry/interface/IIdentityRegistry.sol";

// ONCHAINID — identities (ERC-734/735) and the identity factory.
import { Identity } from "@onchain-id/solidity/contracts/Identity.sol";
import { ImplementationAuthority } from
    "@onchain-id/solidity/contracts/proxy/ImplementationAuthority.sol";
import { IdFactory } from "@onchain-id/solidity/contracts/factory/IdFactory.sol";

import { MockKYCClaimIssuer } from "../src/mocks/MockKYCClaimIssuer.sol";

/// @title TREXSuiteDeployer
/// @notice Reusable, broadcast-context deployment of a full ERC-3643 (T-REX) suite plus the
///         RoughNet mock KYC claim issuer (ADR-0002, ADR-0005). The functions are `internal`,
///         so they execute in the caller's context: the deploy script broadcasts them as the
///         deployer EOA, and Foundry tests run them as the test contract. This keeps the
///         canonical Tokeny deployment sequence in exactly one place.
abstract contract TREXSuiteDeployer {
    /// @notice ERC-3643 claim topic used for the KYC/AML attestation. The real Ctrl Alt issuer
    ///         must sign claims under the same topic for the integration swap to be transparent.
    uint256 internal constant KYC_TOPIC = uint256(keccak256("KYC"));

    /// @notice Every deployed address an operator or the frontend needs.
    struct Suite {
        address token; // ERC-3643 permissioned token (Fraction Token placeholder, Epic 3)
        address identityRegistry; // gate: isVerified() drives every transfer
        address identityRegistryStorage;
        address trustedIssuersRegistry;
        address claimTopicsRegistry;
        address modularCompliance;
        address claimIssuer; // MockKYCClaimIssuer (Ctrl Alt seam #11)
        address idFactory; // ONCHAINID factory for Subscriber identities
        address trexFactory;
    }

    /// @notice Deploy the implementations, wire the implementation authorities and factories,
    ///         then deploy a token suite whose only trusted issuer is the mock KYC issuer.
    /// @param owner   Address that ends up owning the token and all registries.
    /// @param agent   Address added as Identity Registry agent (registers/whitelists Subscribers)
    ///                and token agent (mints, freezes). The KYC backend holds this key in R1.
    /// @param issuerKey Address whose signatures the mock issuer accepts as valid KYC claims;
    ///                  this is the management key of {MockKYCClaimIssuer}.
    function _deployFullSuite(address owner, address agent, address issuerKey)
        internal
        returns (Suite memory s)
    {
        // 1. ERC-3643 implementation contracts (logic behind the proxies the factory deploys).
        Token tokenImpl = new Token();
        ClaimTopicsRegistry ctrImpl = new ClaimTopicsRegistry();
        TrustedIssuersRegistry tirImpl = new TrustedIssuersRegistry();
        IdentityRegistryStorage irsImpl = new IdentityRegistryStorage();
        IdentityRegistry irImpl = new IdentityRegistry();
        ModularCompliance mcImpl = new ModularCompliance();

        // 2. ONCHAINID identity factory (issues Subscriber ONCHAINIDs).
        Identity identityImpl = new Identity(address(this), true); // isLibrary = true
        ImplementationAuthority identityIA = new ImplementationAuthority(address(identityImpl));
        IdFactory idFactory = new IdFactory(address(identityIA));

        // 3. T-REX implementation authority pinned to the implementations above.
        TREXImplementationAuthority trexIA =
            new TREXImplementationAuthority(true, address(0), address(0));
        trexIA.addAndUseTREXVersion(
            ITREXImplementationAuthority.Version({ major: 4, minor: 0, patch: 0 }),
            ITREXImplementationAuthority.TREXContracts({
                tokenImplementation: address(tokenImpl),
                ctrImplementation: address(ctrImpl),
                irImplementation: address(irImpl),
                irsImplementation: address(irsImpl),
                tirImplementation: address(tirImpl),
                mcImplementation: address(mcImpl)
            })
        );

        // 4. Factory, authorised to create token ONCHAINIDs via the id factory.
        TREXFactory trexFactory = new TREXFactory(address(trexIA), address(idFactory));
        idFactory.addTokenFactory(address(trexFactory));

        // 5. The RoughNet-controlled mock KYC claim issuer (replaced by Ctrl Alt, issue #11).
        MockKYCClaimIssuer claimIssuer = new MockKYCClaimIssuer(issuerKey);

        // 6. Deploy the token suite: one claim topic (KYC), one trusted issuer (the mock).
        uint256[] memory claimTopics = new uint256[](1);
        claimTopics[0] = KYC_TOPIC;

        address[] memory issuers = new address[](1);
        issuers[0] = address(claimIssuer);

        uint256[][] memory issuerClaims = new uint256[][](1);
        issuerClaims[0] = claimTopics;

        address[] memory agents = new address[](1);
        agents[0] = agent;

        trexFactory.deployTREXSuite(
            "RNF",
            ITREXFactory.TokenDetails({
                owner: owner,
                name: "RoughNet Fraction (demo)",
                symbol: "RNF",
                decimals: 0, // fraction economics land in Epic 3; identity gating is topic-agnostic
                irs: address(0), // deploy a fresh identity registry storage
                ONCHAINID: address(0), // let the factory create the token's ONCHAINID
                irAgents: agents,
                tokenAgents: agents,
                complianceModules: new address[](0),
                complianceSettings: new bytes[](0)
            }),
            ITREXFactory.ClaimDetails({
                claimTopics: claimTopics,
                issuers: issuers,
                issuerClaims: issuerClaims
            })
        );

        // 7. Recover deployed proxy addresses from the token.
        address token = trexFactory.getToken("RNF");
        IIdentityRegistry ir = IToken(token).identityRegistry();

        s = Suite({
            token: token,
            identityRegistry: address(ir),
            identityRegistryStorage: address(ir.identityStorage()),
            trustedIssuersRegistry: address(ir.issuersRegistry()),
            claimTopicsRegistry: address(ir.topicsRegistry()),
            modularCompliance: address(IToken(token).compliance()),
            claimIssuer: address(claimIssuer),
            idFactory: address(idFactory),
            trexFactory: address(trexFactory)
        });
    }
}

