        bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);
        bytes memory signature = abi.encodePacked(r, s, v);

        // addClaim must be called by a key on the identity; the wallet is its management key.
        vm.prank(wallet);
        IIdentity(identity).addClaim(KYC_TOPIC, 1, suite.claimIssuer, signature, data, "");

        ir.registerIdentity(wallet, IIdentity(identity), 840); // 840 = US country code
    }

    function test_provisionedWalletsAreVerified() public {
        assertTrue(ir.isVerified(alice), "alice should be verified");
        assertTrue(ir.isVerified(bob), "bob should be verified");
        assertFalse(ir.isVerified(carol), "carol never passed KYC");
    }

    function test_transferBetweenWhitelisted_succeeds() public {
        token.mint(alice, 100);

        vm.prank(alice);
        token.transfer(bob, 40);

        assertEq(token.balanceOf(alice), 60);
        assertEq(token.balanceOf(bob), 40);
    }

    function test_transferToNonWhitelisted_reverts() public {
        token.mint(alice, 100);

        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(carol, 10);
    }

    function test_mintToNonWhitelisted_reverts() public {
        vm.expectRevert("Identity is not verified.");
        token.mint(carol, 1);
    }

    /// @notice Compliance admin revokes a wallet's registration -> it can no longer receive.
    function test_revokeIdentityRegistration_blocksIncomingTransfer() public {
        token.mint(alice, 100);
        assertTrue(ir.isVerified(bob));

        ir.deleteIdentity(bob); // agent action

        assertFalse(ir.isVerified(bob));
        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(bob, 10);
    }

    /// @notice Issuer revokes the KYC claim itself -> verification fails, transfers blocked.
    function test_revokeClaim_blocksIncomingTransfer() public {
        token.mint(alice, 100);

        bytes32 claimId = keccak256(abi.encode(suite.claimIssuer, KYC_TOPIC));
        address bobIdentity = address(ir.identity(bob));

        vm.prank(issuer); // management key of the mock claim issuer
        IClaimIssuer(suite.claimIssuer).revokeClaim(claimId, bobIdentity);

        assertFalse(ir.isVerified(bob), "revoked claim should fail verification");
        vm.prank(alice);
        vm.expectRevert("Transfer not possible");
        token.transfer(bob, 10);
    }

    /// @notice Freezing a wallet immediately blocks it from sending (regulator hold).
    function test_freezeWallet_blocksOutgoingTransfer() public {
        token.mint(alice, 100);

        token.setAddressFrozen(alice, true); // agent action

        vm.prank(alice);
        vm.expectRevert("wallet is frozen");
        token.transfer(bob, 10);
    }
}

