import { readOnChainState } from "@/lib/serverReads";
import { RegistryDemo } from "@/components/RegistryDemo";

export default async function HomePage() {
  const onChain = await readOnChainState();

  return (
    <main>
      <h1>RoughNet</h1>
      <p className="muted">
        Walking skeleton — tokenization &amp; fractionalization of rough diamond Specials.
      </p>

      <section className="panel">
        <h2>On-chain state (server read)</h2>
        <p className="muted">
          Network: <code>{onChain.chainName}</code> (chainId {onChain.chainId})
        </p>
        {onChain.address ? (
          <p className="muted">
            Registry: <code>{onChain.address}</code>
          </p>
        ) : null}
        {onChain.error ? (
          <p className="muted">⚠ {onChain.error}</p>
        ) : (
          <p>
            Note: <strong>{onChain.note}</strong> · updates: {onChain.updateCount}
          </p>
        )}
      </section>

      <RegistryDemo />
    </main>
  );
}

