import type { Abi, Address } from "viem";

/**
 * ABI for RoughNetRegistry (packages/contracts/src/RoughNetRegistry.sol).
 * Kept as a hand-maintained subset for the walking skeleton; a later issue can
 * generate this from the Foundry build artifacts.
 */
export const registryAbi = [
  {
    type: "constructor",
    inputs: [{ name: "initialNote", type: "string" }],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "note",
    inputs: [],
    outputs: [{ type: "string" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "updateCount",
    inputs: [],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "lastUpdatedBy",
    inputs: [],
    outputs: [{ type: "address" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "setNote",
    inputs: [{ name: "newNote", type: "string" }],
    outputs: [],
    stateMutability: "nonpayable",
  },
  {
    type: "event",
    name: "NoteUpdated",
    inputs: [
      { name: "by", type: "address", indexed: true },
      { name: "note", type: "string", indexed: false },
