import { NextResponse } from "next/server";
import { isAddress } from "viem";
import { KycNotConfiguredError, provisionKyc } from "@/lib/kyc/issuer";

export const dynamic = "force-dynamic";

/**
 * Mock KYC endpoint (issue #2). Always approves the connected self-custody wallet and issues
 * a real on-chain ERC-3643 KYC claim for it. This is the Ctrl Alt seam — see lib/kyc/issuer.ts
 * and the `ctrl-alt-integration` issue #11.
 */
export async function POST(request: Request) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const wallet = (json as { wallet?: unknown })?.wallet;
  if (typeof wallet !== "string" || !isAddress(wallet)) {
    return NextResponse.json({ error: "Missing or invalid `wallet` address" }, { status: 400 });
  }

  try {
    const result = await provisionKyc(wallet);
    return NextResponse.json(result, { status: 200 });
  } catch (err) {
    if (err instanceof KycNotConfiguredError) {
      return NextResponse.json({ error: err.message }, { status: 501 });
    }
    const message = err instanceof Error ? err.message : "KYC provisioning failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

