"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useState } from "react";
import { useAccount, useReadContract } from "wagmi";
import { getIdentityRegistry, identityRegistryAbi } from "@/lib/kyc/config";

/**
 * Live KYC / claim status for the connected self-custody wallet (issue #2, FR1.6).
 * R1 is MetaMask / WalletConnect only — no embedded or custodial wallets (ADR-0006).
 *
 * Status is read straight from the on-chain ERC-3643 Identity Registry (`isVerified`), so it
 * reflects the real claim state — including admin revocation. The "Run KYC" button calls the
 * mock KYC endpoint (the Ctrl Alt seam, issue #11), then refetches.
 */
export function KycStatus() {
  const { address, chainId, isConnected } = useAccount();
  const identityRegistry = chainId ? getIdentityRegistry(chainId) : undefined;

  const [pending, setPending] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  const verified = useReadContract({
    abi: identityRegistryAbi,
    address: identityRegistry,
    functionName: "isVerified",
    args: address ? [address] : undefined,
    query: { enabled: Boolean(identityRegistry && address) },
  });

  const runKyc = async () => {
    if (!address) return;
    setPending(true);
    setMessage(null);
    try {
      const res = await fetch("/api/kyc", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ wallet: address }),
      });
      const json = (await res.json()) as { error?: string; verified?: boolean };
      if (!res.ok) {
        setMessage(`⚠ ${json.error ?? "KYC failed"}`);
      } else {
        setMessage(json.verified ? "✓ KYC approved and claim issued." : "Claim issued; verifying…");
        await verified.refetch();
      }
    } catch (err) {
      setMessage(`⚠ ${err instanceof Error ? err.message : "KYC request failed"}`);
    } finally {
      setPending(false);
    }
  };

  const isVerified = verified.data === true;

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>KYC &amp; on-chain whitelist (self-custody)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to check your KYC status.</p>
      ) : !identityRegistry ? (
        <p className="muted">
          No identity suite deployed on the connected chain (chainId {chainId}).
        </p>
      ) : (
        <>
          <p>
            Status:{" "}
            {verified.isLoading ? (
              <strong>checking…</strong>
            ) : isVerified ? (
              <strong style={{ color: "#1a7f37" }}>✓ Verified — you can hold and transfer</strong>
            ) : (
              <strong style={{ color: "#9a6700" }}>Not verified</strong>
            )}
          </p>
          <p className="muted">
            What you can do: {isVerified ? "subscribe, receive and transfer Fraction Tokens." : "pass KYC to be whitelisted."}
          </p>
          {!isVerified ? (
            <div className="row">
              <button onClick={runKyc} disabled={pending}>
                {pending ? "Running KYC…" : "Run mock KYC"}
              </button>
            </div>
          ) : null}
          {message ? <p className="muted">{message}</p> : null}
        </>
      )}
    </section>
  );
}

