/// @notice Mirrors the exact on-chain steps the mock KYC backend performs
///         (apps/web/lib/kyc/issuer.ts): create an identity managed by the ops key,
///         attach an issuer-signed claim from that key, then register the wallet.
function test_backendProvisioningPath_verifiesAndTransacts() public {
    address wallet = vm.addr(0xDADA);

    bytes32[] memory managementKeys = new bytes32[](1);
    managementKeys[0] = keccak256(abi.encode(address(this))); // ops key manages the identity
    address identity = IIdFactory(suite.idFactory).createIdentityWithManagementKeys(
        wallet, "backend", managementKeys
    );

    bytes memory data = abi.encode("backend", "KYC:ok");
    bytes32 dataHash = keccak256(abi.encode(identity, KYC_TOPIC, data));
    bytes32 prefixed = keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", dataHash));
    (uint8 v, bytes32 r, bytes32 s) = vm.sign(ISSUER_PK, prefixed);

    // No prank: the ops key (address(this)) is the identity's management key.
    IIdentity(identity).addClaim(KYC_TOPIC, 1, suite.claimIssuer, abi.encodePacked(r, s, v), data, "");
    ir.registerIdentity(wallet, IIdentity(identity), 840);

    assertTrue(ir.isVerified(wallet), "backend-provisioned wallet should verify");

    token.mint(wallet, 25);
    vm.prank(wallet);
    token.transfer(alice, 25);
    assertEq(token.balanceOf(alice), 25);
}

/// @notice Freezing a wallet immediately blocks it from sending (regulator hold).

