import "server-only";
import {
  type Address,
  type Hex,
  createPublicClient,
  createWalletClient,
  encodeAbiParameters,
  http,
  keccak256,
  stringToHex,
  zeroAddress,
} from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { base, polygon, sepolia } from "viem/chains";
import { defaultChain, defaultChainId } from "@/lib/chains";
import { KYC_TOPIC, getKycContracts, idFactoryAbi, identityAbi, identityRegistryAbi } from "./config";

/**
 * Mock KYC claim issuer — the R1 stand-in for Ctrl Alt's production KYC + ONCHAINID claim
 * service (BRD FR1.8/FR1.9). The boundary is this module: `provisionKyc` always approves
 * (the mock KYC decision) and then performs the *real* on-chain ERC-3643 steps — create a
 * Subscriber ONCHAINID, attach a claim signed by the RoughNet-controlled mock issuer key, and
 * register the wallet in the Identity Registry. The on-chain verification path is therefore
 * identical to production; only this off-chain approval is mocked.
 *
 * Replacing it with Ctrl Alt is an integration swap (issue #11): Ctrl Alt runs the KYC and
 * pushes the signed claim; this module's job collapses to "ask Ctrl Alt, await their claim".
 *
 * The single ops key below must be: owner of the IdFactory, an Identity Registry agent, and a
 * claim-signer key of the mock claim issuer. The deploy script wires all three to the deployer
 * by default, so one key suffices in R1.
 */

const RPC_URL: Record<number, string | undefined> = {
  [sepolia.id]: process.env.NEXT_PUBLIC_SEPOLIA_RPC_URL,
  [polygon.id]: process.env.NEXT_PUBLIC_POLYGON_RPC_URL,
  [base.id]: process.env.NEXT_PUBLIC_BASE_RPC_URL,
  31337: "http://127.0.0.1:8545",
};

export interface KycResult {
  ok: true;
  wallet: Address;
  identity: Address;
  verified: boolean;
  alreadyVerified: boolean;
  createdIdentity: boolean;
  txHashes: Hex[];
}

/** Thrown for configuration problems (missing key/addresses) so the route can return 501. */
export class KycNotConfiguredError extends Error {}

function requireAgentKey(): Hex {
  const key = process.env.KYC_AGENT_PRIVATE_KEY;
  if (!key) {
    throw new KycNotConfiguredError(
      "KYC_AGENT_PRIVATE_KEY is not set; cannot issue mock KYC claims.",
    );
  }
  return (key.startsWith("0x") ? key : `0x${key}`) as Hex;
}

/** keccak256(abi.encode(addr)) — the ONCHAINID key hash used by ERC-734. */
function keyHash(addr: Address): Hex {
  return keccak256(encodeAbiParameters([{ type: "address" }], [addr]));
}

/**
 * Approve KYC for `wallet` and make it verifiable on-chain. Idempotent: re-running for an
 * already-verified wallet is a no-op that reports the existing identity.
 */
export async function provisionKyc(wallet: Address): Promise<KycResult> {
  const contracts = getKycContracts(defaultChainId);
  if (!contracts) {
    throw new KycNotConfiguredError(
      `KYC suite addresses are not configured for chain ${defaultChainId}.`,
    );
  }

  const account = privateKeyToAccount(requireAgentKey());
  if (account.address.toLowerCase() === wallet.toLowerCase()) {
    throw new KycNotConfiguredError(
      "Connected wallet is the KYC ops key; connect a different wallet for the demo.",
    );
  }

  const transport = http(RPC_URL[defaultChainId]);
  const publicClient = createPublicClient({ chain: defaultChain, transport });
  const walletClient = createWalletClient({ account, chain: defaultChain, transport });

  const txHashes: Hex[] = [];
  const send = async (hash: Hex) => {
    txHashes.push(hash);
    await publicClient.waitForTransactionReceipt({ hash });
  };

  // Already verified? Nothing to do.
  const alreadyVerified = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "isVerified",
    args: [wallet],
  });
  if (alreadyVerified) {
    const identity = await publicClient.readContract({
      address: contracts.identityRegistry,
      abi: identityRegistryAbi,
      functionName: "identity",
      args: [wallet],
    });
    return {
      ok: true,
      wallet,
      identity,
      verified: true,
      alreadyVerified: true,
      createdIdentity: false,
      txHashes,
    };
  }

  // 1. Ensure the wallet has an ONCHAINID (managed by the ops key so it can attach the claim).
  let identity = await publicClient.readContract({
    address: contracts.idFactory,
    abi: idFactoryAbi,
    functionName: "getIdentity",
    args: [wallet],
  });
  let createdIdentity = false;
  if (identity === zeroAddress) {
    const hash = await walletClient.writeContract({
      address: contracts.idFactory,
      abi: idFactoryAbi,
      functionName: "createIdentityWithManagementKeys",
      args: [wallet, wallet.toLowerCase(), [keyHash(account.address)]],
    });
    await send(hash);
    identity = await publicClient.readContract({
      address: contracts.idFactory,
      abi: idFactoryAbi,
      functionName: "getIdentity",
      args: [wallet],
    });
    createdIdentity = true;
  }

  // 2. Sign the KYC claim with the mock issuer key and attach it to the identity.
  //    Matches ClaimIssuer.isClaimValid: sign the Ethereum-prefixed keccak of
  //    abi.encode(identity, topic, data).
  const data = stringToHex("KYC verified by RoughNet mock issuer (R1)");
  const dataHash = keccak256(
    encodeAbiParameters(
      [{ type: "address" }, { type: "uint256" }, { type: "bytes" }],
      [identity, KYC_TOPIC, data],
    ),
  );
  const signature = await walletClient.signMessage({ account, message: { raw: dataHash } });

  const addClaimHash = await walletClient.writeContract({
    address: identity,
    abi: identityAbi,
    functionName: "addClaim",
    args: [KYC_TOPIC, 1n, contracts.claimIssuer, signature, data, ""],
  });
  await send(addClaimHash);

  // 3. Register the wallet -> identity link in the Identity Registry (idempotent guard).
  const registered = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "identity",
    args: [wallet],
  });
  if (registered === zeroAddress) {
    const registerHash = await walletClient.writeContract({
      address: contracts.identityRegistry,
      abi: identityRegistryAbi,
      functionName: "registerIdentity",
      args: [wallet, identity, 840], // 840 = US; country is informational without a country module
    });
    await send(registerHash);
  }

  const verified = await publicClient.readContract({
    address: contracts.identityRegistry,
    abi: identityRegistryAbi,
    functionName: "isVerified",
    args: [wallet],
  });

  return { ok: true, wallet, identity, verified, alreadyVerified: false, createdIdentity, txHashes };
}

